if(!defined('ABSPATH')){exit;}
function au_defaults(){return json_decode(file_get_contents(__DIR__.'/defaults.json'),true);}
function au_config(){return wp_parse_args(get_option('au_config',array()),au_defaults());}
function au_settings(){return wp_parse_args(get_option('au_settings',array()),array('demo'=>1,'test'=>1,'recipient'=>'','privacy'=>'','retention'=>120));}
function au_error($message,$status=400){return new WP_Error('aurelia_error',$message,array('status'=>$status));}
function au_find($items,$id){foreach($items as $i){if($i['id']===$id){return $i;}}return null;}
function au_time($date,$time){$dt=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$date.' '.$time,new DateTimeZone(au_config()['timezone']));return $dt&&$dt->format('Y-m-d H:i')===$date.' '.$time?$dt:null;}
function au_minutes($time){$v=explode(':',$time);return (int)$v[0]*60+(int)$v[1];}
function au_slot_keys($provider,$stamp,$duration){$keys=array();for($t=$stamp;$t<$stamp+$duration*60;$t+=900){$keys[]='au_slot_'.$provider.'_'.$t;}return $keys;}
function au_slots($service,$provider,$date,$ignore=0,$duration_override=0){
 $c=au_config();$s=au_find($c['services'],$service);$p=au_find($c['providers'],$provider);$d=au_time($date,'12:00');if(!$s||!$p||!$d||!in_array($service,$p['services'],true)){return array();}
 if($duration_override){$s['duration']=(int)$duration_override;}
 $now=new DateTimeImmutable('now',new DateTimeZone($c['timezone']));if($date<$now->format('Y-m-d')||$date>$now->modify('+'.$c['horizon_days'].' days')->format('Y-m-d')||in_array($date,$c['closed_dates'],true)){return array();}
 $day=(int)$d->format('w');if(!$day||!in_array($day,$p['days'],true)){return array();}$hours=$day===6?$c['hours']['saturday']:$c['hours']['weekday'];$start=max(au_minutes($p['start']),au_minutes($hours[0]));$end=min(au_minutes($p['end']),au_minutes($hours[1]));$slots=array();
 for($n=$start;$n+(int)$s['duration']<=$end;$n+=15){$time=sprintf('%02d:%02d',intdiv($n,60),$n%60);$stamp=au_time($date,$time)->getTimestamp();if($stamp<time()+$c['lead_hours']*3600){continue;}$free=true;foreach(au_slot_keys($provider,$stamp,$s['duration']) as $key){$held=get_option($key,false);if($held!==false&&(string)$held!==(string)$ignore){$free=false;break;}}if($free){$slots[]=$time;}}
 return $slots;
}
function au_lock($provider,$stamp,$duration,$owner,$ignore=0){$claimed=array();foreach(au_slot_keys($provider,$stamp,$duration) as $key){$held=get_option($key,false);if($ignore&&$held!==false&&(string)$held===(string)$ignore){continue;}if(!add_option($key,$owner,'','no')){foreach($claimed as $k){delete_option($k);}return false;}$claimed[]=$key;}return $claimed;}
function au_release($keys,$owner){foreach($keys as $key){if((string)get_option($key)===(string)$owner){delete_option($key);}}}
function au_origin($r){$origin=$r->get_header('origin');if($origin&&untrailingslashit($origin)!==untrailingslashit((string)preg_replace('#^(https?://[^/]+).*$#','$1',home_url()))){return au_error('Request origin is not allowed.',403);}return true;}
function au_challenge(){ $stamp=time();$random=wp_generate_password(32,false,false);$r=new WP_REST_Response(array('stamp'=>$stamp,'challenge'=>$random,'signature'=>hash_hmac('sha256',$stamp.'.'.$random,wp_salt('nonce'))));$r->header('Cache-Control','no-store, private');return $r;}
function au_guard($r){
 $s=au_settings();if($s['demo']||!is_email($s['recipient'])||!$s['privacy']){return au_error('Demo mode does not accept real submissions.',503);}if(strlen($r->get_body())>12000){return au_error('Request is too large.',413);}$x=$r->get_json_params();if(!is_array($x)){return au_error('Invalid request.');}
 foreach($x as $k=>$v){if(!is_scalar($v)){return au_error('Invalid field.');}}
 $stamp=$x['stamp']??0;$challenge=$x['challenge']??'';$signature=$x['signature']??'';
 if(!is_int($stamp)||!is_string($challenge)||!preg_match('/^[a-zA-Z0-9]{32}$/',$challenge)||!is_string($signature)||time()-$stamp<2||time()-$stamp>1200||!hash_equals(hash_hmac('sha256',$stamp.'.'.$challenge,wp_salt('nonce')),$signature)){return au_error('Refresh the form, wait a moment and try again.',403);}
 if(!empty($x['website'])){return au_error('Unable to accept request.');}
 $rate='au_rate_'.hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'unknown',wp_salt());if((int)get_transient($rate)>=10){return au_error('Too many requests. Please try again in an hour.',429);}set_transient($rate,(int)get_transient($rate)+1,HOUR_IN_SECONDS);
 if(!add_option('au_once_'.hash('sha256',$challenge),time(),'','no')){return au_error('This request was already submitted. Refresh the form.',409);}return $x;
}
function au_contact_data($x,$booking=true){
 $d=array();foreach(array('name'=>100,'email'=>180,'phone'=>32,'notes'=>500,'message'=>2000,'category'=>100,'service'=>40,'provider'=>40,'date'=>10,'time'=>5) as $k=>$max){$v=$x[$k]??'';if(!is_string($v)||strlen($v)>$max*4){return au_error('Invalid '.$k.'.');}$d[$k]=$k==='notes'||$k==='message'?sanitize_textarea_field($v):sanitize_text_field($v);}
 if(strlen(trim($d['name']))<2||!is_email($d['email'])||($x['consent']??'')!=='yes'){return au_error('Enter a name, valid email and policy consent.');}if(($booking||$d['phone'])&&!preg_match('/^[0-9+().\s-]{7,32}$/',$d['phone'])){return au_error('Enter a valid phone number.');}if(!$booking&&strlen($d['message'])<10){return au_error('Please provide a message of at least 10 characters.');}return $d;
}
function au_book($r){
 $x=au_guard($r);if(is_wp_error($x)){return $x;}$d=au_contact_data($x);if(is_wp_error($d)){return $d;}$c=au_config();$s=au_find($c['services'],$d['service']);if(!$s||!in_array($d['time'],au_slots($d['service'],$d['provider'],$d['date']),true)){return au_error('This time is unavailable. Choose another slot.',409);}
 $stamp=au_time($d['date'],$d['time'])->getTimestamp();$reference='AUR-'.strtoupper(substr(wp_generate_uuid4(),0,12));$token=bin2hex(random_bytes(24));$keys=au_lock($d['provider'],$stamp,$s['duration'],$reference);if($keys===false){return au_error('This slot was just reserved. Choose another time.',409);}
 $id=wp_insert_post(array('post_type'=>'au_appointment','post_status'=>'private','post_title'=>$reference),true);if(is_wp_error($id)){au_release($keys,$reference);return au_error('Unable to save appointment. Please try again.',503);}
 $d['duration']=$s['duration'];$d['price']=$s['price'];$d['service_name']=$s['name'];$d['stamp']=$stamp;$d['status']='confirmed';$d['reference']=$reference;$d['consent_at']=gmdate('c');update_post_meta($id,'_au_data',$d);update_post_meta($id,'_au_token_hash',hash('sha256',$token));update_post_meta($id,'_au_keys',$keys);au_notify($id,$token);au_schedule_reminder($id,$stamp);$out=new WP_REST_Response(array('reference'=>$reference,'message'=>'Appointment reserved. Confirmation is queued through the configured mail transport.'),201);$out->header('Cache-Control','no-store');return $out;
}
function au_schedule_reminder($id,$stamp){wp_clear_scheduled_hook('au_reminder',array($id));if($stamp-86400>time()){wp_schedule_single_event($stamp-86400,'au_reminder',array($id));}}
function au_notify($id,$token='',$kind='confirmation'){
 $d=get_post_meta($id,'_au_data',true);$s=au_settings();if(!$d||$s['demo']||!is_email($s['recipient'])){return false;}$to=$s['test']?$s['recipient']:$d['email'];$body="Aurelia appointment ".$kind."\nReference: ".$d['reference']."\nService: ".$d['service_name']."\nDate: ".$d['date'].' '.$d['time']." (America/New_York)\nStatus: ".$d['status']."\nPay at studio. Sample price: $".$d['price']."\n";
 if($token){$body.="\nPrivate management code: ".$token."\nKeep this code private. Manage your booking at ".home_url('/booking/')."\n";}$body.="Do not reply with sensitive health information.";
 $ok=wp_mail($to,($s['test']?'[TEST] ':'').'Aurelia '.$kind.' '.$d['reference'],$body);update_post_meta($id,'_au_mail',$ok?'accepted':'failed');if(!$s['test']){wp_mail($s['recipient'],'Studio appointment update '.$d['reference'],$body);}return $ok;
}
add_action('au_reminder',function($id){$d=get_post_meta($id,'_au_data',true);if($d&&$d['status']==='confirmed'&&$d['stamp']>time()){au_notify($id,'','reminder');}});
function au_manage($r){
 if(au_settings()['demo']){return au_error('Appointment management is disabled in demo mode.',503);}if(strlen($r->get_body())>3000){return au_error('Invalid request.');}$x=$r->get_json_params();if(!is_array($x)){return au_error('Invalid request.');}foreach($x as $v){if(!is_string($v)){return au_error('Invalid request.');}}
 $rate='au_manage_'.hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'unknown',wp_salt());if((int)get_transient($rate)>=20){return au_error('Please try again later.',429);}set_transient($rate,(int)get_transient($rate)+1,HOUR_IN_SECONDS);
 $posts=get_posts(array('post_type'=>'au_appointment','post_status'=>'private','title'=>sanitize_text_field($x['reference']??''),'numberposts'=>1));$id=$posts?$posts[0]->ID:0;
 if(!$id||!hash_equals((string)get_post_meta($id,'_au_token_hash',true),hash('sha256',$x['token']??''))){return au_error('Reference or management code is incorrect.',403);}if(!add_option('au_mutex_'.$id,time(),'','no')){return au_error('Another update is in progress. Please try again.',409);}
 try{$d=get_post_meta($id,'_au_data',true);if($d['status']!=='confirmed'){return au_error('This appointment is no longer active.',409);}if($d['stamp']-time()<au_config()['cancel_hours']*3600){return au_error('Online changes are closed. Please contact the studio.',403);}$action=$x['action']??'';
 if($action==='cancel'){$d['status']='cancelled';update_post_meta($id,'_au_data',$d);au_release(get_post_meta($id,'_au_keys',true),$d['reference']);wp_clear_scheduled_hook('au_reminder',array($id));au_notify($id,'','cancellation');return array('message'=>'Appointment cancelled.');}
 if($action!=='reschedule'){return au_error('Invalid action.');}$date=$x['date']??'';$time=$x['time']??'';if(!in_array($time,au_slots($d['service'],$d['provider'],$date,$d['reference'],$d['duration']),true)){return au_error('The new time is unavailable.',409);}$stamp=au_time($date,$time)->getTimestamp();$keys=au_lock($d['provider'],$stamp,$d['duration'],$d['reference'],$d['reference']);if($keys===false){return au_error('The new time was just booked.',409);}$allkeys=au_slot_keys($d['provider'],$stamp,$d['duration']);$old=get_post_meta($id,'_au_keys',true);$d['date']=$date;$d['time']=$time;$d['stamp']=$stamp;update_post_meta($id,'_au_data',$d);update_post_meta($id,'_au_keys',$allkeys);au_release(array_diff($old,$allkeys),$d['reference']);au_schedule_reminder($id,$stamp);au_notify($id,'','reschedule');return array('message'=>'Appointment rescheduled.');
 }finally{delete_option('au_mutex_'.$id);}
}
function au_lead($r){$x=au_guard($r);if(is_wp_error($x)){return $x;}$d=au_contact_data($x,false);if(is_wp_error($d)){return $d;}$d['source']='website contact';$d['status']='New';$d['assigned']='';$d['consent_at']=gmdate('c');$id=wp_insert_post(array('post_type'=>'au_lead','post_status'=>'private','post_title'=>'Inquiry '.wp_generate_uuid4()),true);if(is_wp_error($id)){return au_error('Unable to save inquiry.',503);}update_post_meta($id,'_au_data',$d);$ok=wp_mail(au_settings()['recipient'],'Aurelia new inquiry',"Name: ".$d['name']."\nEmail: ".$d['email']."\nCategory: ".$d['category']."\nRequested service: ".$d['service']."\nMessage: ".$d['message']);update_post_meta($id,'_au_mail',$ok?'accepted':'failed');return new WP_REST_Response(array('message'=>'Inquiry received.'),201);}
add_action('rest_api_init',function(){foreach(array('challenge'=>array('GET','au_challenge'),'slots'=>array('GET',function($r){$response=new WP_REST_Response(array('slots'=>au_slots(sanitize_key($r['service']),sanitize_key($r['provider']),sanitize_text_field($r['date']))));$response->header('Cache-Control','no-store');return $response;}),'book'=>array('POST','au_book'),'manage'=>array('POST','au_manage'),'lead'=>array('POST','au_lead')) as $path=>$route){register_rest_route('aurelia/v1','/'.$path,array('methods'=>$route[0],'callback'=>$route[1],'permission_callback'=>'au_origin'));}});
add_action('init',function(){foreach(array('au_appointment'=>'Appointments','au_lead'=>'Studio inquiries') as $type=>$title){register_post_type($type,array('label'=>$title,'public'=>false,'publicly_queryable'=>false,'show_ui'=>true,'show_in_rest'=>false,'supports'=>array('title'),'map_meta_cap'=>false,'capabilities'=>array('edit_post'=>'manage_options','read_post'=>'manage_options','delete_post'=>'manage_options','edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','read_private_posts'=>'manage_options','delete_posts'=>'manage_options','delete_private_posts'=>'manage_options','delete_published_posts'=>'manage_options','delete_others_posts'=>'manage_options','edit_private_posts'=>'manage_options','edit_published_posts'=>'manage_options','create_posts'=>'do_not_allow')));}});
add_action('before_delete_post',function($id){if(get_post_type($id)==='au_appointment'){$d=get_post_meta($id,'_au_data',true);au_release((array)get_post_meta($id,'_au_keys',true),$d['reference']??'');wp_clear_scheduled_hook('au_reminder',array($id));}});
function au_resolve($html){return function_exists('aurelia_resolve')?aurelia_resolve($html):$html;}
foreach(array('booking','contact'=>'lead','manage') as $key=>$name){$tag=is_int($key)?$name:$key;add_shortcode('aurelia_'.$tag,function()use($name){$f=au_resolve(file_get_contents(__DIR__.'/'.$name.'.html'));if(!au_settings()['demo']&&$name==='lead'){$f=str_replace('Demo form: previews locally; nothing is sent.','Your inquiry is stored privately for the studio to respond.',$f);$f=str_replace('Preview inquiry','Send inquiry',$f);}return $f;});}
add_shortcode('aurelia_services',function($attrs){$attrs=shortcode_atts(array('limit'=>6),$attrs);$h='<div class="service-grid">';foreach(array_slice(au_config()['services'],0,max(1,min(6,(int)$attrs['limit']))) as $s){$h.='<article class="service-card"><a href="'.esc_url(home_url('/service/?id='.$s['id'])).'"><img src="'.esc_url(get_theme_file_uri('assets/'.$s['image'].'.webp')).'" alt="Stock service inspiration" loading="lazy"><div class="card-copy"><span class="eyebrow">'.esc_html($s['category']).'</span><h3>'.esc_html($s['name']).'</h3><p>'.esc_html($s['description']).'</p><div class="card-meta">From $'.esc_html($s['price']).' · '.esc_html($s['duration']).' min <span>↗</span></div></div></a></article>';}return $h.'</div>';});
add_shortcode('aurelia_service',function(){return '<div id="service-detail"></div>';});
add_action('admin_menu',function(){add_menu_page('Aurelia Studio','Aurelia Studio','manage_options','aurelia-studio','au_admin','dashicons-calendar-alt',26);});
function au_admin(){
 if(!current_user_can('manage_options')){return;}$c=au_config();$s=au_settings();$notice='';if(isset($_POST['au_save'])){check_admin_referer('au_save');$raw=wp_unslash($_POST);$recipient=sanitize_email($raw['recipient']??'');$privacy=esc_url_raw($raw['privacy']??'');$demo=isset($raw['demo'])?1:0;if(!$demo&&(!is_email($recipient)||!wp_http_validate_url($privacy))){$demo=1;$notice='Demo mode kept on: valid recipient and public privacy URL required.';}$s=array('demo'=>$demo,'test'=>isset($raw['test'])?1:0,'recipient'=>$recipient,'privacy'=>$privacy,'retention'=>max(7,min(365,absint($raw['retention']??120))));
 foreach($c['services'] as &$v){$a=$raw['services'][$v['id']]??array();$v['name']=sanitize_text_field($a['name']??$v['name']);$v['description']=sanitize_textarea_field($a['description']??$v['description']);$v['price']=max(0,min(10000,(float)($a['price']??$v['price'])));$v['duration']=max(15,min(180,(int)(round((int)($a['duration']??$v['duration'])/15)*15)));}unset($v);
 foreach($c['providers'] as &$v){$a=$raw['providers'][$v['id']]??array();$v['name']=sanitize_text_field($a['name']??$v['name']);$v['days']=array_values(array_filter(array_map('intval',(array)($a['days']??array())),fn($x)=>$x>=1&&$x<=6));foreach(array('start','end') as $k){if(preg_match('/^(?:[01][0-9]|2[0-3]):(?:00|15|30|45)$/',$a[$k]??'')){$v[$k]=$a[$k];}}if($v['start']>=$v['end']){$v['start']='09:00';$v['end']='19:00';}}unset($v);
 $c['closed_dates']=array_values(array_filter(array_map('trim',explode(',',sanitize_textarea_field($raw['closed_dates']??''))),fn($x)=>au_time($x,'12:00')!==null));update_option('au_config',$c);update_option('au_settings',$s);$notice=$notice?:'Settings saved.';}
 echo '<div class="wrap"><h1>Aurelia Studio</h1><p>Manage catalogue, schedules and test delivery. All times: America/New_York. Email accepted means accepted by transport, not confirmed inbox delivery.</p>';if($notice){echo '<div class="notice notice-info"><p>'.esc_html($notice).'</p></div>';}
 echo '<p><a class="button" href="'.esc_url(admin_url('edit.php?post_type=au_appointment')).'">Appointments</a> <a class="button" href="'.esc_url(admin_url('edit.php?post_type=au_lead')).'">Lead inbox</a></p>';au_calendar();
 echo '<form method="post">';wp_nonce_field('au_save');echo '<h2>Delivery & privacy</h2><p><label><input type="checkbox" name="demo" '.checked($s['demo'],1,false).'> Demo mode: do not accept server submissions</label></p><p><label><input type="checkbox" name="test" '.checked($s['test'],1,false).'> Route ALL notifications to the test inbox below</label></p><p><label>Approved studio/test inbox <input type="email" name="recipient" value="'.esc_attr($s['recipient']).'"></label></p><p><label>Approved privacy policy URL <input type="url" name="privacy" value="'.esc_attr($s['privacy']).'" class="regular-text"></label></p><p><label>Retention days <input type="number" min="7" max="365" name="retention" value="'.esc_attr($s['retention']).'"></label></p><p>Only disable test routing on an approved production site. Configure authenticated SMTP separately. Retention cleanup permanently deletes expired inquiries and past appointments; backups need a separate policy.</p><h2>Services</h2>';
 foreach($c['services'] as $v){$n='services['.$v['id'].']';echo '<fieldset style="padding:12px;border:1px solid #ccc;margin:10px 0"><legend>'.esc_html($v['id']).'</legend><label>Name <input name="'.esc_attr($n.'[name]').'" value="'.esc_attr($v['name']).'" class="regular-text"></label> <label>Price $ <input type="number" step="0.01" min="0" name="'.esc_attr($n.'[price]').'" value="'.esc_attr($v['price']).'"></label> <label>Minutes <input type="number" min="15" max="180" step="15" name="'.esc_attr($n.'[duration]').'" value="'.esc_attr($v['duration']).'"></label><p><textarea name="'.esc_attr($n.'[description]').'" rows="2" class="large-text">'.esc_textarea($v['description']).'</textarea></p></fieldset>';}
 echo '<h2>Provider schedules</h2><p>Business limits: Mon–Fri 09:00–19:00; Saturday 10:00–17:00; Sunday closed. Existing appointments retain their originally reserved duration and price.</p>';
 foreach($c['providers'] as $v){$n='providers['.$v['id'].']';echo '<fieldset style="padding:12px;border:1px solid #ccc"><legend>'.esc_html($v['title']).'</legend><label>Display name <input name="'.esc_attr($n.'[name]').'" value="'.esc_attr($v['name']).'"></label> <label>Start <input type="time" step="900" name="'.esc_attr($n.'[start]').'" value="'.esc_attr($v['start']).'"></label> <label>End <input type="time" step="900" name="'.esc_attr($n.'[end]').'" value="'.esc_attr($v['end']).'"></label><p>';foreach(array(1=>'Mon',2=>'Tue',3=>'Wed',4=>'Thu',5=>'Fri',6=>'Sat') as $day=>$label){echo '<label><input type="checkbox" name="'.esc_attr($n.'[days][]').'" value="'.$day.'" '.checked(in_array($day,$v['days']),true,false).'>'.$label.'</label> ';}echo '</p></fieldset>';}
 echo '<p><label>Unavailable dates (YYYY-MM-DD, comma-separated)<br><textarea class="large-text" name="closed_dates">'.esc_textarea(implode(', ',$c['closed_dates'])).'</textarea></label></p>';submit_button('Save studio settings','primary','au_save');echo '</form></div>';
}
function au_calendar(){ $month=isset($_GET['month'])?sanitize_text_field(wp_unslash($_GET['month'])):wp_date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month)){$month=wp_date('Y-m');}$start=au_time($month.'-01','12:00');if(!$start){return;}$posts=get_posts(array('post_type'=>'au_appointment','post_status'=>'private','numberposts'=>-1));$by=array();foreach($posts as $p){$d=get_post_meta($p->ID,'_au_data',true);if($d&&str_starts_with($d['date'],$month)){$by[(int)substr($d['date'],8)][]=array($p->ID,$d);}}echo '<h2>Appointment calendar — '.esc_html($start->format('F Y')).'</h2><p>';foreach(array('-1 month'=>'← Previous','+1 month'=>'Next →') as $move=>$label){echo '<a class="button" href="'.esc_url(add_query_arg(array('page'=>'aurelia-studio','month'=>$start->modify($move)->format('Y-m')),admin_url('admin.php'))).'">'.$label.'</a> ';}echo '</p><table class="widefat"><thead><tr>';foreach(array('Sun','Mon','Tue','Wed','Thu','Fri','Sat') as $v){echo '<th>'.$v.'</th>';}echo '</tr></thead><tbody><tr>';$offset=(int)$start->format('w');for($i=0;$i<$offset;$i++){echo '<td></td>';}for($day=1;$day<=(int)$start->format('t');$day++){echo '<td style="vertical-align:top;height:65px"><strong>'.$day.'</strong>';foreach($by[$day]??array() as $row){echo '<p><a href="'.esc_url(get_edit_post_link($row[0])).'">'.esc_html($row[1]['time'].' '.$row[1]['service_name'].' · '.$row[1]['status']).'</a></p>';}echo '</td>';if(($day+$offset)%7===0){echo '</tr><tr>';}}echo '</tr></tbody></table>';}
add_action('add_meta_boxes',function(){foreach(array('au_appointment','au_lead') as $type){add_meta_box('au-record','Private studio record','au_record',$type);}});
function au_record($p){if(!current_user_can('manage_options')){return;}$d=get_post_meta($p->ID,'_au_data',true);wp_nonce_field('au_record','au_record_nonce');echo '<table class="widefat">';foreach((array)$d as $k=>$v){echo '<tr><th>'.esc_html($k).'</th><td>'.nl2br(esc_html((string)$v)).'</td></tr>';}echo '</table><p>Mail: '.esc_html(get_post_meta($p->ID,'_au_mail',true)).'</p>';if($p->post_type==='au_lead'){echo '<p><label>Status <select name="au_lead_status">';foreach(array('New','Contacted','Consultation Scheduled','Closed') as $v){echo '<option '.selected($d['status'],$v,false).'>'.esc_html($v).'</option>';}echo '</select></label> <label>Assigned staff <input name="au_assigned" value="'.esc_attr($d['assigned']??'').'"></label></p>';}else{echo '<p><label><input type="checkbox" name="au_cancel"> Cancel this appointment and release its slots</label></p><p><label><input type="checkbox" name="au_resend"> Resend confirmation with a new management code (old code becomes invalid)</label></p>';}}
add_action('save_post',function($id){if(!current_user_can('manage_options')||!isset($_POST['au_record_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['au_record_nonce'])),'au_record')||wp_is_post_revision($id)){return;}$d=get_post_meta($id,'_au_data',true);if(!$d){return;}if(get_post_type($id)==='au_lead'){$status=sanitize_text_field(wp_unslash($_POST['au_lead_status']??''));if(in_array($status,array('New','Contacted','Consultation Scheduled','Closed'),true)){$d['status']=$status;}$d['assigned']=sanitize_text_field(wp_unslash($_POST['au_assigned']??''));update_post_meta($id,'_au_data',$d);}elseif(get_post_type($id)==='au_appointment'){if(!add_option('au_mutex_'.$id,time(),'','no')){return;}try{$d=get_post_meta($id,'_au_data',true);if(isset($_POST['au_cancel'])){$d['status']='cancelled';update_post_meta($id,'_au_data',$d);au_release((array)get_post_meta($id,'_au_keys',true),$d['reference']);wp_clear_scheduled_hook('au_reminder',array($id));au_notify($id,'','cancellation');}elseif(isset($_POST['au_resend'])){$token=bin2hex(random_bytes(24));update_post_meta($id,'_au_token_hash',hash('sha256',$token));au_notify($id,$token);}}finally{delete_option('au_mutex_'.$id);}}});
function au_cleanup(){ $before=time()-au_settings()['retention']*DAY_IN_SECONDS;foreach(get_posts(array('post_type'=>array('au_lead','au_appointment'),'post_status'=>'private','numberposts'=>100,'date_query'=>array(array('before'=>gmdate('Y-m-d H:i:s',$before))))) as $p){$d=get_post_meta($p->ID,'_au_data',true);if($p->post_type==='au_lead'||($d['stamp']??PHP_INT_MAX)<$before){wp_delete_post($p->ID,true);}}global $wpdb;$wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name LIKE %s AND CAST(option_value AS UNSIGNED) < %d",$wpdb->esc_like('au_once_').'%',time()-DAY_IN_SECONDS));}
add_action('au_cleanup','au_cleanup');register_activation_hook(__FILE__,function(){if(!wp_next_scheduled('au_cleanup')){wp_schedule_event(time()+3600,'daily','au_cleanup');}});register_deactivation_hook(__FILE__,function(){wp_clear_scheduled_hook('au_cleanup');wp_clear_scheduled_hook('au_reminder');});
